    std::uint64_t aWandererI = 0U; std::uint64_t aWandererJ = 0U; std::uint64_t aWandererK = 0U;

    // [twist]
    aIngress = 0xA76F4D717B449524ULL;
    aCarry = 0xAC402A9E1F5B9F16ULL;
    aWandererA = 0xD93CCD4F097A5BAAULL;
    aWandererB = 0xFAAE8F3DF1BC6979ULL;
    aWandererC = 0x9DFFC681E7745724ULL;
    aWandererD = 0xD8014B2E867C2282ULL;
    aWandererE = 0x8118233357122D0CULL;
    aWandererF = 0xE6B7F50A50E163B3ULL;
    aWandererG = 0xE03369EF3D3CD05BULL;
    aWandererH = 0xE6D347BA5C325E32ULL;
    aWandererI = 0xC3A8E4DCC2A201C4ULL;
    aWandererJ = 0x93E36C9DE4063628ULL;
    aWandererK = 0xA4535FAD4D56C396ULL;

    TwistExpander_Suhail_Arx::TWIST_A(PARAMS_TWIST);

    TwistExpander_Suhail_Arx::TWIST_B(PARAMS_TWIST);

    TwistExpander_Suhail_Arx::TWIST_C(PARAMS_TWIST);

    //
    std::uint64_t aDomainWordMatrixSelectA = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixSelectA;
    std::uint64_t aDomainWordMatrixSelectB = pWorkSpace->mDomainBundle.mTwistConstants.mMatrixSelectB;

